import { ProfilePatch } from './types';

const invalid = () => new Error('invalid profile');

export function parseProfile(input: unknown): ProfilePatch {
  if (typeof input !== 'object' || input === null || Array.isArray(input)) throw invalid();
  const proto = Object.getPrototypeOf(input);
  if (proto !== Object.prototype && proto !== null) throw invalid();

  const data: Record<string, unknown> = {};
  for (const key of Reflect.ownKeys(input)) {
    if (key !== 'displayName' && key !== 'tags') throw invalid();
    const desc = Object.getOwnPropertyDescriptor(input, key)!;
    if (!('value' in desc)) throw invalid();
    data[key] = desc.value;
  }

  let displayName: ProfilePatch['displayName'] = { kind: 'keep' };
  let tags: ProfilePatch['tags'] = { kind: 'keep' };

  if ('displayName' in data) {
    const v = data.displayName;
    if (v === null) displayName = { kind: 'set', value: null };
    else if (typeof v === 'string') {
      const t = v.trim();
      if (t.length < 1 || t.length > 40) throw invalid();
      displayName = { kind: 'set', value: t };
    } else throw invalid();
  }

  if ('tags' in data) {
    const v = data.tags;
    if (v === null) tags = { kind: 'set', value: [] };
    else if (Array.isArray(v)) {
      if (v.length > 5) throw invalid();
      const out: string[] = [];
      for (let i = 0; i < v.length; i++) {
        if (!(i in v)) throw invalid();
        const item = v[i];
        if (typeof item !== 'string') throw invalid();
        const t = item.trim();
        if (t.length < 1 || t.length > 12 || out.includes(t)) throw invalid();
        out.push(t);
      }
      tags = { kind: 'set', value: out };
    } else throw invalid();
  }
  return { displayName, tags };
}

